// TH18 v1.00a st05mbs.ecl.txt MBoss/MBoss1. Source attack t0 = target frame 124.
// Entry state comes from MBoss setup: (0,128), no residual velocity, moveLimit(0,128,280,256).
// Source setInterrupt(1,0,1500,"MBossDead"); 120-frame shell buffer gives 1622.
const TIME_LIMIT: int = 1622;
const SOURCE_LIMIT: int = 1500;
const OPENING_BUFFER: int = 120;
const TH18_KUNAI: int = 496;

// moveRand(200,0,0.3): angle fixed, speed 0.3*(200-k)/200 for source ticks k=1..200.
// Inner steering region is center +- width/4 = x +-70, y 64..192;
// actual clamp is center +- size/2 = x[-140,140], y[0,256].
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 200 { speed = ((200 - k) as fx) * 0.3fx / 200fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 0fx { ny = 0fx; }
    if ny > 256fx { ny = 256fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
// Source 412 moveRand: signed pi*U angle selection, then the +-pi/2 guard.
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 64fx {
        if a < 0 { a = -a; }
    } else if $self_y > 192fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
// Advance the source movement ticks while the script waits, as the engine does.
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// M:62-108. Two fixed fans: slot0 rank 1/3/5/7 at the loop's 10deg step,
// slot1 17 at the loop's 18.5deg step (the earlier 32/20deg configs are overwritten).
// B is the player angle sampled once per call; floatTime mode1 gives D=A*n^2/900
// at the n-th 12-frame boundary. C starts opposite B.
sub mboss1_at(a: angle) {
    var until: int = self_int(1);
    sh_reset(0);
    sh_sprite(0, TH18_KUNAI, 13);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_speed(0, 2.7fx, 0fx);
    sh_dist(0, -10.8fx); // ANIM type2 a=1: position -= 4*initial velocity.
    sh_reset(1);
    sh_sprite(1, TH18_KUNAI, 10);
    sh_ring(1, 0);
    sh_aim(1, 0);
    sh_count(1, 17, 1);
    sh_speed(1, 4fx, 0fx);
    sh_dist(1, -16fx);
    var rank: int = global(GVAR_RANK);
    var n0: int = 1;
    if rank == 1 { n0 = 3; }
    if rank == 2 { n0 = 5; }
    if rank >= 3 { n0 = 7; }
    sh_count(0, n0, 1);
    var b: angle = aim_player();
    var c: angle = b + 180deg;
    for i in 0..30 {
        if $frame >= until { return; }
        sh_angle(0, b, 10deg);
        sh_offset_rad(0, b - 90deg, 70fx);
        sh_fire(0);
        sh_offset_rad(0, b + 90deg, 70fx);
        sh_fire(0);
        sh_angle(1, c, 18.5deg);
        sh_offset_rad(1, b - 90deg, 70fx);
        sh_fire(1);
        sh_offset_rad(1, b + 90deg, 70fx);
        sh_fire(1);
        card_wait(12);
        var d: int = (a as int) * (i + 1) * (i + 1) / 900;
        b = b + (d as angle);
    }
}

// M:45-58. I0=60/I1=1 have no reader in this attack. Each MBoss1_at is 360
// source frames, then the 30-frame wait; the timeout can cut the fourth call.
async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(24fx);
    set_hitbox(20fx);
    wait(OPENING_BUFFER);
    var until: int = $frame + SOURCE_LIMIT;
    set_self_int(1, until);
    loop {
        if $frame >= until { return; }
        card_move_rand();
        mboss1_at(10deg);
        if $frame >= until { return; }
        card_wait(30);
        if $frame >= until { return; }
        card_move_rand();
        mboss1_at(-10deg);
        if $frame >= until { return; }
        card_wait(30);
    }
}

async sub wave() {
    _ = spawn_enemy(0fx, 128fx, 13000, 0, 0, 0, boss_main);
    wait(TIME_LIMIT);
    loop { wait(600); }
}

async sub encounter() {
    // Training-only phase owner at (0,0); source body collision belongs to the real boss.
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
